CREATE TABLE accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL, join_code TEXT, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX index_accounts_on_join_code ON accounts(join_code);
CREATE TABLE folders (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id INTEGER NOT NULL REFERENCES accounts(id), created_at TEXT NOT NULL, name TEXT, updated_at TEXT NOT NULL);
CREATE INDEX index_folders_on_account_id ON folders(account_id);
CREATE TABLE sinks (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id INTEGER NOT NULL REFERENCES accounts(id), created_at TEXT NOT NULL, folder_id INTEGER REFERENCES folders(id), name TEXT NOT NULL, token TEXT, updated_at TEXT NOT NULL);
CREATE INDEX index_sinks_on_account_id ON sinks(account_id);
CREATE INDEX index_sinks_on_folder_id ON sinks(folder_id);
CREATE INDEX index_sinks_on_name ON sinks(name);
CREATE UNIQUE INDEX index_sinks_on_token ON sinks(token);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id INTEGER REFERENCES accounts(id), created_at TEXT NOT NULL, current_folder_id INTEGER REFERENCES folders(id) ON DELETE SET NULL, current_sink_id INTEGER REFERENCES sinks(id) ON DELETE SET NULL, email_address TEXT NOT NULL, nickname TEXT, password_digest TEXT NOT NULL, role INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE INDEX index_users_on_account_id ON users(account_id);
CREATE INDEX index_users_on_current_folder_id ON users(current_folder_id);
CREATE INDEX index_users_on_current_sink_id ON users(current_sink_id);
CREATE UNIQUE INDEX index_users_on_email_address ON users(email_address);
CREATE TABLE sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL, ip_address TEXT, updated_at TEXT NOT NULL, user_agent TEXT, user_id INTEGER NOT NULL REFERENCES users(id));
CREATE INDEX index_sessions_on_user_id ON sessions(user_id);
CREATE TABLE sink_memberships (id INTEGER PRIMARY KEY AUTOINCREMENT, column_last_viewed_at TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(column_last_viewed_at)), created_at TEXT NOT NULL, has_unread_events INTEGER NOT NULL DEFAULT 0 CHECK(has_unread_events IN (0,1)), last_viewed_at TEXT, sink_id INTEGER NOT NULL REFERENCES sinks(id), unread_count INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id));
CREATE INDEX index_sink_memberships_on_sink_id ON sink_memberships(sink_id);
CREATE INDEX index_sink_memberships_on_user_id ON sink_memberships(user_id);
CREATE UNIQUE INDEX index_sink_memberships_on_user_id_and_sink_id ON sink_memberships(user_id,sink_id);
CREATE TABLE columns (id INTEGER PRIMARY KEY AUTOINCREMENT, config TEXT CHECK(config IS NULL OR json_valid(config)), created_at TEXT NOT NULL, has_events INTEGER NOT NULL DEFAULT 0 CHECK(has_events IN (0,1)), name TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, sink_id INTEGER NOT NULL REFERENCES sinks(id), updated_at TEXT NOT NULL);
CREATE INDEX index_columns_on_sink_id ON columns(sink_id);
CREATE INDEX index_columns_on_sink_id_and_position ON columns(sink_id,position);
CREATE TABLE saved_views (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL, event_date TEXT, event_type TEXT, name TEXT NOT NULL, property_key TEXT, property_op TEXT, property_value TEXT, search_query TEXT, sink_id INTEGER NOT NULL REFERENCES sinks(id), updated_at TEXT NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id));
CREATE INDEX index_saved_views_on_sink_id ON saved_views(sink_id);
CREATE INDEX index_saved_views_on_user_id ON saved_views(user_id);
CREATE INDEX index_saved_views_on_sink_id_and_user_id ON saved_views(sink_id,user_id);
CREATE UNIQUE INDEX index_saved_views_on_user_id_and_sink_id_and_name ON saved_views(user_id,sink_id,name);
CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL, emoji TEXT NOT NULL DEFAULT '📌' CHECK(length(emoji)<=8), event_type TEXT NOT NULL, idempotency_key TEXT CHECK(idempotency_key IS NULL OR length(idempotency_key)<=255), occurred_at TEXT NOT NULL, properties TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(properties)), sdk_name TEXT, sdk_version TEXT, search_text TEXT NOT NULL, sink_id INTEGER NOT NULL REFERENCES sinks(id), text TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX index_events_on_event_type ON events(event_type);
CREATE INDEX index_events_on_sink_id ON events(sink_id);
CREATE INDEX index_events_on_sink_id_and_occurred_at ON events(sink_id,occurred_at DESC,id DESC);
CREATE UNIQUE INDEX index_events_on_sink_id_and_idempotency_key ON events(sink_id,idempotency_key);
CREATE TABLE schema_migrations (version TEXT PRIMARY KEY NOT NULL);
CREATE TABLE ar_internal_metadata (key TEXT PRIMARY KEY NOT NULL, value TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE telesink_schema_migrations (version TEXT PRIMARY KEY NOT NULL);
CREATE TABLE telesink_imported_jobs (active_job_id TEXT PRIMARY KEY NOT NULL, payload_hash TEXT NOT NULL, kind TEXT NOT NULL, imported_at TEXT NOT NULL);
CREATE TABLE telesink_changes (id INTEGER PRIMARY KEY AUTOINCREMENT, payload TEXT NOT NULL);
CREATE TRIGGER telesink_changes_bounded AFTER INSERT ON telesink_changes BEGIN DELETE FROM telesink_changes WHERE id <= NEW.id - 512; END;
